<div class="chips"><?php foreach(['Semua','Menunggu Penawaran','Diproses','Dikirim','Disewa','Selesai','Belum Lunas'] as $s): ?><a class="chip <?= ($_GET['status']??'')===$s?'active':'' ?>" href="?page=pesanan<?= $s==='Semua'?'':'&status='.urlencode($s) ?>"><?= h($s) ?></a><?php endforeach; ?></div><section class="panel"><div class="panel-head"><div><h2>Daftar Pesanan</h2><p>Perbarui status sesuai proses operasional</p></div></div><div class="table-wrap"><table><thead><tr><th>No. Pesanan</th><th>Pelanggan</th><th>Proyek</th><th>Tgl Pengajuan</th><th>Durasi</th><th>Status</th><th>Ubah Status</th></tr></thead><tbody><?php foreach($store['pesanan'] as $i=>$o): if(!empty($_GET['status']) && $o['status']!==$_GET['status'])continue; ?><tr><td><b><?= h($o['kode']) ?></b></td><td><?= h($o['pelanggan']) ?></td><td><?= h($o['proyek']) ?></td><td><?= h($o['tanggal']) ?></td><td><?= h($o['durasi']) ?></td><td><?= status_badge($o['status']) ?></td><td><form method="post" class="inline-form"><?= csrf_field() ?><input type="hidden" name="action" value="update_status"><input type="hidden" name="index" value="<?= $i ?>"><select class="field compact" name="status"><option><?= h($o['status']) ?></option><?php foreach(['Menunggu Penawaran','Diproses','Menunggu DP','Dikirim','Disewa','Selesai','Belum Lunas','Dibatalkan'] as $next): if($next===$o['status'])continue; ?><option><?= h($next) ?></option><?php endforeach; ?></select><button class="icon-btn" title="Simpan status">✓</button></form></td></tr><?php endforeach; ?></tbody></table></div></section>
